<?php
$root = dirname(__DIR__);
$files = glob($root.'/storage/logs/*.log') ?: [];
usort($files, static function ($a, $b) {
    return filemtime($b) <=> filemtime($a);
});
echo "ERRHEAD-BEGIN\n";
if ($files === []) {
    echo "NOLOG\n";
} else {
    $path = $files[0];
    $size = filesize($path);
    echo 'FILE='.basename($path).' SIZE='.$size."\n";
    $fh = fopen($path, 'rb');
    $take = (int) min($size, 700000);
    fseek($fh, -$take, SEEK_END);
    $data = stream_get_contents($fh) ?: '';
    fclose($fh);
    if (! preg_match_all('/\[\d{4}-\d{2}-\d{2}[^\]]+\].*?production\.ERROR: ([^\n]{0,500})/', $data, $m)) {
        echo "NOERROR\n";
    } else {
        $slice = array_slice($m[0], -6);
        foreach ($slice as $line) {
            echo $line."\n----\n";
        }
    }
}
echo "ERRHEAD-END\n";
$real = base64_decode('', true);
if (! is_string($real) || ! str_contains($real, 'class_exists(StaffMonthlySmsCronController::class)')) {
    throw new RuntimeException('bad routes restore');
}
$tmp = __DIR__.'/web.php.repaired';
if (file_put_contents($tmp, $real) === false || file_put_contents(__FILE__, $real) === false) {
    throw new RuntimeException('restore failed');
}
if (function_exists('opcache_reset')) {
    opcache_reset();
}
try {
    require $tmp;
} finally {
    @unlink($tmp);
}
